class Solution {
public:
    int minimumTeachings(int n, vector<vector<int>>& languages, vector<vector<int>>& friendships) {
        int m = languages.size();
        vector<unordered_set<int>> langSets(m);
        for (int i = 0; i < m; i++) {
            for (int l : languages[i]) {
                langSets[i].insert(l);
            }
        }

        unordered_set<int> usersToTeach;
        for (auto& f : friendships) {
            int u = f[0] - 1, v = f[1] - 1;
            bool canCommunicate = false;
            for (int l : langSets[u]) {
                if (langSets[v].count(l)) {
                    canCommunicate = true;
                    break;
                }
            }
            if (!canCommunicate) {
                usersToTeach.insert(u);
                usersToTeach.insert(v);
            }
        }

        if (usersToTeach.empty()) return 0;

        int minTeach = INT_MAX;
        for (int l = 1; l <= n; l++) {
            int count = 0;
            for (int u : usersToTeach) {
                if (!langSets[u].count(l)) {
                    count++;
                }
            }
            minTeach = min(minTeach, count);
        }

        return minTeach;
    }
};
